def solve(n=13, fixed={1:12,11:1}):
    cols=set(); d1=set(); d2=set(); q=[None]*n
    # Maybe process rows in order with MRV? fixed first
    for r,c in fixed.items():
        if c in cols or (r-c) in d1 or (r+c) in d2:
            return None
        cols.add(c); d1.add(r-c); d2.add(r+c); q[r]=c
    rows=[r for r in range(n) if r not in fixed]
    # recursive MRV choose row with min avail
    def bt():
        if all(x is not None for x in q):
            return q.copy()
        # choose unassigned row min options
        best=None; opts=None
        for r in range(n):
            if q[r] is None:
                av=[c for c in range(n) if c not in cols and (r-c) not in d1 and (r+c) not in d2]
                if opts is None or len(av)<len(opts):
                    best=r; opts=av
                    if len(opts)==0: break
        if not opts:
            return None
        r=best
        for c in opts:
            q[r]=c; cols.add(c); d1.add(r-c); d2.add(r+c)
            res=bt()
            if res: return res
            cols.remove(c); d1.remove(r-c); d2.remove(r+c); q[r]=None
        return None
    return bt()
